#!/usr/bin/env python3
"""Condense a captured conversation JSONL into readable turns.

argv: <jsonl path> [max-chars-per-turn]
Prints: timestamp, role, and text content only. Tool calls are reduced to
name + a short argument digest; tool results to their first line.
"""
import json
import sys

path = sys.argv[1]
cap = int(sys.argv[2]) if len(sys.argv) > 2 else 700

for line in open(path, encoding='utf-8', errors='replace'):
    line = line.strip()
    if not line:
        continue
    try:
        e = json.loads(line)
    except Exception:
        continue
    ts = (e.get('timestamp') or '')[11:19]
    msg = e.get('message') or {}
    role = e.get('type') or msg.get('role') or ''
    content = msg.get('content')
    if isinstance(content, str):
        content = [{'type': 'text', 'text': content}]
    if not isinstance(content, list):
        continue
    for block in content:
        if not isinstance(block, dict):
            continue
        t = block.get('type')
        if t == 'text':
            txt = (block.get('text') or '').strip()
            if txt:
                print(f'[{ts}] {role}: {txt[:cap]}')
        elif t == 'thinking':
            txt = (block.get('thinking') or '').strip()
            if txt:
                print(f'[{ts}] think: {txt[:cap]}')
        elif t == 'tool_use':
            args = json.dumps(block.get('input') or {})[:200]
            print(f'[{ts}] TOOL {block.get("name")} {args}')
        elif t == 'tool_result':
            c = block.get('content')
            if isinstance(c, list):
                c = ' '.join(b.get('text', '') for b in c if isinstance(b, dict))
            c = (c or '') if isinstance(c, str) else str(c)
            first = c.strip().splitlines()[0][:160] if c.strip() else ''
            err = ' ERR' if block.get('is_error') else ''
            print(f'[{ts}] result{err}: {first}')

