#!/usr/bin/env python3
"""Survey captured logs: duration, turn counts, and genuine owner turns.

argv: <dir of jsonl files>
A harness pseudo-turn starts with '<' (a tag envelope) or is a tool_result
carrier; those are not the owner speaking.
"""
import datetime
import json
import os
import sys

d = sys.argv[1]
for name in sorted(os.listdir(d)):
    if not name.endswith('.jsonl'):
        continue
    first = last = None
    humans = []
    tools = 0
    for line in open(os.path.join(d, name), encoding='utf-8', errors='replace'):
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except Exception:
            continue
        ts = e.get('timestamp')
        if ts:
            first = first or ts
            last = ts
        msg = e.get('message') or {}
        content = msg.get('content')
        if isinstance(content, str):
            content = [{'type': 'text', 'text': content}]
        if not isinstance(content, list):
            continue
        for b in content:
            if not isinstance(b, dict):
                continue
            if b.get('type') == 'tool_use':
                tools += 1
            if e.get('type') == 'user' and b.get('type') == 'text':
                txt = (b.get('text') or '').strip()
                if txt and not txt.startswith('<') and not txt.startswith('[Request'):
                    humans.append(txt[:120].replace('\n', ' '))
    dur = ''
    if first and last:
        try:
            a = datetime.datetime.fromisoformat(first.replace('Z', '+00:00'))
            b2 = datetime.datetime.fromisoformat(last.replace('Z', '+00:00'))
            dur = f'{(b2 - a).total_seconds() / 60:.0f}m'
        except Exception:
            pass
    print(f'{name}  dur={dur} tools={tools} owner_turns={len(humans)}')
    for h in humans[:12]:
        print(f'    > {h}')

