#!/usr/bin/env python3
"""Print a capture's genuine owner turns in full, each with the assistant text
that followed it.

argv: <jsonl path> [reply-chars]
"""
import json
import sys

path = sys.argv[1]
reply_cap = int(sys.argv[2]) if len(sys.argv) > 2 else 900

entries = []
for line in open(path, encoding='utf-8', errors='replace'):
    line = line.strip()
    if not line:
        continue
    try:
        entries.append(json.loads(line))
    except Exception:
        pass


def texts(e):
    msg = e.get('message') or {}
    c = msg.get('content')
    if isinstance(c, str):
        c = [{'type': 'text', 'text': c}]
    if not isinstance(c, list):
        return []
    return [b.get('text', '') for b in c if isinstance(b, dict) and b.get('type') == 'text']


for i, e in enumerate(entries):
    if e.get('type') != 'user':
        continue
    for txt in texts(e):
        t = txt.strip()
        if not t or t.startswith('<') or t.startswith('[Request') or t.startswith('Base directory for this skill'):
            continue
        print(f'\n===== OWNER [{(e.get("timestamp") or "")[11:19]}] =====')
        print(t[:2500])
        shown = 0
        for j in range(i + 1, min(i + 40, len(entries))):
            if entries[j].get('type') == 'user':
                break
            for rt in texts(entries[j]):
                rt = rt.strip()
                if rt:
                    print(f'--- agent: {rt[:reply_cap]}')
                    shown += 1
            if shown >= 3:
                break

